'use strict';
const $=s=>document.querySelector(s);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons={people:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2 M16 3a4 4 0 0 1 0 8 M22 21v-2a4 4 0 0 0-3-3.87 M13 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0',grid:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',calendar:'M8 2v4 M16 2v4 M3 10h18 M5 4h14a2 2 0 0 1 2 2v14H3V6a2 2 0 0 1 2-2',check:'m5 12 4 4L19 6',mail:'M3 5h18v14H3z m0 0 9 7 9-7',link:'M10 13a5 5 0 0 0 7 0l3-3a5 5 0 0 0-7-7l-2 2 M14 11a5 5 0 0 0-7 0l-3 3a5 5 0 0 0 7 7l2-2',search:'M21 21l-5-5 M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0',plus:'M12 5v14 M5 12h14',file:'M14 2H4v20h16V8z M14 2v6h6 M8 13h8 M8 17h6',arrow:'m14 6-6 6 6 6',clock:'M12 8v5l3 2 M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',hat:'m2 9 10-5 10 5-10 5z M6 11v6q6 5 12 0v-6 M22 9v7'};
const icon=n=>`<svg class="icon" aria-hidden="true" viewBox="0 0 24 24"><path d="${icons[n]||icons.file}"/></svg>`;
function brandLogo(compact=false){return `<span class="brand-lockup ${compact?'compact':''}"><span class="brand-mark" aria-hidden="true"><img class="brand-logo-image" src="granted-logo-mark.jpg" width="132" height="161" alt=""></span>${compact?'':`<span class="brand-copy"><strong>${esc(crmSettings.organization||'GrantEd')}</strong><small>Admissions CRM</small></span>`}</span>`}
const levels=['Бакалавриат','Магистратура','PhD'];
const statuses=['Подбор программы','Документы','Подана','Интервью','Оффер','Отказ'];
const today=new Date();today.setHours(0,0,0,0);
const iso=d=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
const dateAt=n=>{const d=new Date(today);d.setDate(d.getDate()+n);return iso(d)};
const fmt=d=>d?new Date(d+'T12:00:00').toLocaleDateString('ru-RU',{day:'numeric',month:'short'}):'Не указан';
const days=d=>d?Math.round((new Date(d+'T00:00:00')-today)/86400000):null;
const uni=[['University of Toronto','Канада','Computer Science'],['University of Amsterdam','Нидерланды','Business Analytics'],['University of Manchester','Великобритания','Management'],['Bocconi University','Италия','Economics'],['Technical University of Munich','Германия','Data Science'],['University of Melbourne','Австралия','Public Policy'],['ETH Zürich','Швейцария','Robotics'],['University of British Columbia','Канада','Engineering']];
function seed(){const first=['Амина','Алихан','Диана','Данияр','Аружан','Тимур','Айлин','Санжар','Мадина','Нурасыл'];const last=['Садыкова','Омаров','Ким','Нурланов','Ахметова','Исаев','Серикова','Толеуов','Каримова','Алиев'];return Array.from({length:100},(_,i)=>{let apps=Array.from({length:2+i%4},(_,j)=>{const u=uni[(i+j)%uni.length];return{id:`a${i}-${j}`,university:u[0],country:u[1],program:u[2],deadline:dateAt(5+(i*3+j*7)%85),status:statuses[(i+j)%6]}});return{id:`c${i+1}`,name:i<10?first[i]+' '+last[i]:first[i%10]+' '+['Абдрахман','Есен','Бекен','Серик','Аман','Нур','Жан','Болат','Асқар'][Math.floor(i/10)-1],email:`applicant${i+1}@example.com`,phone:'',level:levels[i%3],year:2027,country:[...new Set(apps.map(a=>a.country))].join(', '),notes:i===0?'Интересует Computer Science. Приоритет — программы со стипендией. Проверить требования к портфолио.':'',folder:'',docs:[],apps,tasks:[{id:`t${i}`,title:['Проверить мотивационное письмо','Запросить рекомендательное письмо','Подготовить резюме','Проверить перевод диплома','Уточнить требования программы'][i%5],date:dateAt(i<5?i-1:7+i%30),done:i%7===6}],demo:true}})}
const KEY='admissions-crm-demo-v1';let clients=[];
let query='',level='',stage='',page=1;const size=10;let toastTimer;
function toast(text){$('#toast').textContent=text;$('#toast').style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').style.display='none',3200)}
async function save(){return serverSave()}
const avatar=(c,i=0)=>`<span class="avatar tone${i%4}">${esc(c.name.split(' ').map(v=>v[0]).slice(0,2).join(''))}</span>`;
const badge=s=>`<span class="badge ${s==='Оффер'?'green':s==='Подана'?'blue':s==='Интервью'||s==='Документы'?'amber':s==='Отказ'?'red':''}">${esc(s)}</span>`;
const cstatus=c=>c.apps.some(a=>a.status==='Оффер')?'Оффер':c.apps.some(a=>a.status==='Интервью')?'Интервью':c.apps.some(a=>a.status==='Подана')?'Подана':'Документы';
const completed=c=>c.apps.filter(a=>['Подана','Интервью','Оффер','Отказ'].includes(a.status)).length;
const allTasks=()=>clients.flatMap(c=>c.tasks.map(t=>({...t,client:c})));
function route(){const parts=(location.hash||'#clients').slice(1).split('/');return {view:parts[0],id:parts[1],tab:parts[2]||'overview'}}
function legacyShell(body,active='clients'){return `<div class="shell"><aside class="sidebar"><a href="#clients" class="brand" aria-label="${esc(crmSettings.organization||'GrantEd')} — главная">${brandLogo()}</a></aside><main class="main"><div class="content">${body}</div></main></div>`}
function stats(){const apps=clients.flatMap(c=>c.apps);return `<div class="stats">${[['Всего клиентов',clients.length,'в текущем рабочем пространстве','people'],['Заявок отправлено',apps.filter(a=>['Подана','Интервью','Оффер','Отказ'].includes(a.status)).length,`из ${apps.length} заявок`,'file'],['Получено офферов',apps.filter(a=>a.status==='Оффер').length,'результаты по университетам','hat'],['Задачи на 7 дней',allTasks().filter(t=>!t.done&&days(t.date)<=7).length,'включая просроченные','clock']].map(([l,n,s,ic])=>`<div class="stat"><div class="label">${l}</div>${icon(ic)}<div class="number">${n}</div><small>${s}</small></div>`).join('')}</div>`}
function listRows(){let found=clients.filter(c=>(!query||`${c.name} ${c.email} ${c.apps.map(a=>a.university).join(' ')}`.toLowerCase().includes(query.toLowerCase()))&&(!level||c.level===level)&&(!stage||cstatus(c)===stage));const pages=Math.max(1,Math.ceil(found.length/size));page=Math.min(page,pages);$('#rows').innerHTML=found.slice((page-1)*size,page*size).map((c,i)=>`<tr><td><div class="person">${avatar(c,i)}<div><a class="name" href="#client/${c.id}">${esc(c.name)}</a><small>${esc(c.email||'Почта не указана')}</small></div></div></td><td>${esc(c.level)}<br><span class="subtle">${c.year}</span></td><td>${completed(c)} из ${c.apps.length}<div class="mini-progress" aria-label="${completed(c)} из ${c.apps.length} заявок отправлено"><span style="width:${c.apps.length?completed(c)/c.apps.length*100:0}%"></span></div></td><td>${badge(cstatus(c))}</td><td>${fmt(c.apps.filter(a=>!['Оффер','Отказ'].includes(a.status)).sort((a,b)=>a.deadline.localeCompare(b.deadline))[0]?.deadline)}</td></tr>`).join('')||'<tr><td colspan="5"><div class="empty">Клиенты не найдены. Попробуйте изменить поиск или фильтры.</div></td></tr>';$('#pagination').innerHTML=`<span>${found.length?`${(page-1)*size+1}–${Math.min(page*size,found.length)}`:'0'} из ${found.length} клиентов</span><div class="btnrow"><button data-page="-1" ${page===1?'disabled':''} aria-label="Предыдущая страница">‹</button><span>${page} / ${pages}</span><button data-page="1" ${page===pages?'disabled':''} aria-label="Следующая страница">›</button></div>`}
function renderList(){const deadlines=allTasks().filter(t=>!t.done).sort((a,b)=>a.date.localeCompare(b.date)).slice(0,4);$('#app').innerHTML=shell(`<div class="heading"><div><h1>Клиенты</h1><p>Все поступления — в одном рабочем пространстве.</p></div><button class="primary" data-action="new-client">${icon('plus')} Добавить клиента</button></div>${stats()}<div class="workspace"><section><div class="section-top"><h2>База клиентов <span class="subtle" style="margin-left:6px">${clients.length}</span></h2><span class="subtle">Набор ${esc(crmSettings.year)}</span></div><div class="filters"><div class="search">${icon('search')}<input id="search" aria-label="Поиск клиентов" placeholder="Имя, почта или университет…" value="${esc(query)}"></div><select id="level" aria-label="Уровень обучения"><option value="">Все уровни</option>${levels.map(l=>`<option ${level===l?'selected':''}>${l}</option>`).join('')}</select><select id="stage" aria-label="Статус клиента"><option value="">Все статусы</option>${['Документы','Подана','Интервью','Оффер'].map(l=>`<option ${stage===l?'selected':''}>${l}</option>`).join('')}</select></div><div class="tablewrap"><table><thead><tr><th>Клиент</th><th>Обучение</th><th>Заявки</th><th>Статус</th><th>Дедлайн</th></tr></thead><tbody id="rows"></tbody></table></div><div id="pagination" class="pagination"></div><p class="local-note">Изменения сохраняются в базе данных. Документы открываются по вашим ссылкам Google Drive.</p></section><aside class="aside"><h2>Требуют внимания</h2><span class="subtle">Ближайшие задачи</span>${deadlines.map(t=>`<div class="deadline"><span class="date-tag ${days(t.date)<0?'overdue':''}">${days(t.date)<0?'Просрочено · ':days(t.date)===0?'Сегодня · ':''}${fmt(t.date)}</span><a href="#client/${t.client.id}/tasks">${esc(t.client.name)}</a><p>${esc(t.title)}</p></div>`).join('')}<a class="quiet-link" href="#tasks">Все задачи</a><div class="note-panel">${icon('link')} <strong style="font-size:12px;margin-left:4px">Документы рядом</strong><p>Добавьте ссылку на папку Google Drive в карточке клиента.</p></div></aside></div>`);listRows()}
function render(){if(typeof crmReady!=='undefined'&&!crmReady)return;const r=route();if(r.view==='client'&&typeof renderClient==='function')renderClient(r);else if(r.view==='tasks'&&typeof renderTasks==='function')renderTasks();else if(r.view==='settings')renderSettings();else if(r.view==='integrations'&&typeof renderIntegrations==='function')renderIntegrations();else renderList()}
document.addEventListener('input',e=>{if(e.target.id==='search'){query=e.target.value;page=1;listRows()}});
document.addEventListener('change',e=>{if(e.target.id==='level'){level=e.target.value;page=1;listRows()}if(e.target.id==='stage'){stage=e.target.value;page=1;listRows()}});
document.addEventListener('click',e=>{const b=e.target.closest('[data-page]');if(b){page+=Number(b.dataset.page);listRows()}});
window.addEventListener('hashchange',render);
function clientById(id){return clients.find(c=>c.id===id)}
function options(items,value){return items.map(s=>`<option value="${esc(s)}" ${s===value?'selected':''}>${esc(s)}</option>`).join('')}
function googleLink(value){try{const u=new URL(value);return u.protocol==='https:'&&['drive.google.com','docs.google.com'].includes(u.hostname)?u.href:''}catch{return ''}}
function showModal(title,body){const d=$('#modal');d.innerHTML=`<div class="modal-head"><h2>${esc(title)}</h2><button data-action="close" aria-label="Закрыть">×</button></div><div class="modal-body">${body}</div>`;if(!d.open)d.showModal()}
function footer(label='Сохранить'){return `<p class="error" id="form-error" role="alert"></p><div class="form-footer"><button type="button" data-action="close">Отмена</button><button type="submit" class="primary">${label}</button></div>`}

const currencies=['USD','EUR','GBP','CAD','AUD','CHF','KZT'];
const feeLabels={unknown:'Не указан',unpaid:'Не оплачен',paid:'Оплачен клиентом',waived:'Без сбора / waiver'};
function fullDate(value){return value?new Date(value+'T12:00:00').toLocaleDateString('ru-RU'):'Не указана'}
function money(amount,currency){return esc(new Intl.NumberFormat('ru-RU',{minimumFractionDigits:2,maximumFractionDigits:2}).format(amount)+' '+currency)}
function validateFee(data){
 const status=data.feeStatus||'unknown', currency=data.feeCurrency||'USD';
 if(!Object.hasOwn(feeLabels,status)||!currencies.includes(currency))throw new Error('Выберите статус оплаты и валюту из списка.');
 let amount=data.feeAmount===''||data.feeAmount==null?null:Number(data.feeAmount);
 if(amount!==null&&(!Number.isFinite(amount)||amount<0||amount>10000000||Math.abs(amount*100-Math.round(amount*100))>0.000001))throw new Error('Укажите неотрицательную сумму с максимум двумя знаками после запятой.');
 if(status==='paid'&&amount===null)throw new Error('Укажите сумму, которую оплатил клиент.');
 if(status==='waived')amount=0;
 const paidDate=status==='paid'?(data.feePaidDate||''):'';
 if(paidDate&&(!/^\d{4}-\d{2}-\d{2}$/.test(paidDate)||!Number.isFinite(Date.parse(paidDate))||paidDate>iso(today)))throw new Error('Дата оплаты должна быть корректной и не позже сегодняшнего дня.');
 return {feeAmount:amount,feeCurrency:currency,feeStatus:status,feePaidDate:paidDate};
}
function feeTotals(apps){const totals={};for(const a of apps){if(a.feeStatus==='paid'&&typeof a.feeAmount==='number'&&Number.isFinite(a.feeAmount)&&a.feeAmount>=0){const currency=a.feeCurrency||'USD';totals[currency]=(totals[currency]||0)+Math.round(a.feeAmount*100)}}return Object.entries(totals).sort(([a],[b])=>a.localeCompare(b)).map(([currency,cents])=>({currency,amount:cents/100}))}
function feeSummary(c){const totals=feeTotals(c.apps);return `<div class="fee-summary"><div><h3>Расходы клиента · application fee</h3><p>Только отмеченные как оплаченные. Валюты считаются отдельно.</p></div><div class="fee-totals">${totals.length?totals.map(t=>`<strong>${money(t.amount,t.currency)}</strong>`).join(''):'<span class="subtle">Оплаченные сборы не внесены</span>'}</div></div>`}
function profileFields(c){return `<label>Направление / поле<input name="academicField" maxlength="300" value="${esc(c?.academicField||'')}" placeholder="IT / Business / Public Policy / Product Management"></label><label>Целевой семестр<select name="semester">${options(['Не указан','Fall','Spring','Summer','Winter'],c?.semester||'Не указан')}</select></label><label>Финансовая стратегия<input name="funding" maxlength="300" value="${esc(c?.funding||'')}" placeholder="Fully Funded and Bolashak"></label><div class="row"><label>Уровень английского (текущий)<input name="english" maxlength="100" value="${esc(c?.english||'')}" placeholder="Advanced"></label><label>Нужен GRE/GMAT?<select name="exam">${options(['Не уточнено','Нет','GRE','GMAT','GRE или GMAT','GRE и GMAT'],c?.exam||'Не уточнено')}</select></label></div><label>Консультант GrantEd<input name="consultant" maxlength="160" value="${esc(c?.consultant||'')}" placeholder="Yernar Kuanyshev"></label><label>Дата старта работы<input name="startDate" type="date" value="${esc(c?.startDate||'')}"></label>`}
function clientOverview(c){const fields=[['ФИО клиента',c.name],['Направление / поле',c.academicField],['Целевые страны',c.country],['Целевой семестр / год',`${c.semester&&c.semester!=='Не указан'?c.semester+' · ':''}${c.year}`],['Финансовая стратегия',c.funding],['Уровень английского (текущий)',c.english],['Нужен GRE/GMAT?',c.exam],['Консультант GrantEd',c.consultant],['Дата старта работы',fullDate(c.startDate)]];return `<div class="section-top"><h2>Информация о клиенте</h2><button data-action="edit-client" data-id="${c.id}">Изменить данные</button></div><dl class="client-info">${fields.map(([label,value])=>`<div><dt>${label}</dt><dd>${esc(value||'Не указано')}</dd></div>`).join('')}<div><dt>Целевые университеты</dt><dd>${c.apps.length?`<a href="#client/${c.id}/applications">${esc([...new Set(c.apps.map(a=>a.university))].join(', '))}</a>`:`<a href="#client/${c.id}/applications">Добавить университеты в разделе «Заявки»</a>`}</dd></div></dl>${feeSummary(c)}${renderClientTests(c)}`}
function feeFields(a){return `<fieldset class="fee-fields"><legend>Application fee</legend><p class="subtle">Укажите сумму сбора по этой заявке. В расходы попадут только оплаченные сборы.</p><div class="row"><label>Сумма сбора<input name="feeAmount" type="number" min="0" max="10000000" step="0.01" value="${a?.feeAmount??''}" placeholder="Например, 90.00"></label><label>Валюта<select name="feeCurrency">${options(currencies,a?.feeCurrency||'USD')}</select></label></div><label>Статус оплаты<select name="feeStatus">${Object.entries(feeLabels).map(([v,l])=>`<option value="${v}" ${v===(a?.feeStatus||'unknown')?'selected':''}>${l}</option>`).join('')}</select></label><label>Дата оплаты (необязательно)<input name="feePaidDate" type="date" max="${iso(today)}" value="${esc(a?.feePaidDate||'')}"></label></fieldset>`}

function clientForm(c){showModal(c?'Редактировать клиента':'Новый клиент',`<form id="client-form" data-id="${c?.id||''}"><label>ФИО клиента<input name="name" required maxlength="100" autocomplete="name" value="${esc(c?.name||'')}" placeholder="Например, Амина Садыкова"></label><div class="row"><label>Уровень обучения<select name="level">${options(levels,c?.level||levels[0])}</select></label><label>Год поступления<input name="year" type="number" min="2020" max="2100" required value="${c?.year||crmSettings.year}"></label></div>${profileFields(c)}<label>Email<input name="email" type="email" autocomplete="email" value="${esc(c?.email||'')}" placeholder="name@gmail.com"></label><label>Телефон для WhatsApp<input name="phone" type="tel" autocomplete="tel" value="${esc(c?.phone||'')}" placeholder="+7 700 000 00 00"></label><label>Целевые страны<input name="country" maxlength="160" value="${esc(c?.country||'')}" placeholder="Канада, Великобритания…"></label><label>Папка Google Drive<input name="folder" type="url" value="${esc(c?.folder||'')}" placeholder="https://drive.google.com/drive/folders/…"></label>${footer(c?'Сохранить изменения':'Добавить клиента')}</form>`)}
function renderClient(r){const c=clientById(r.id);if(!c){$('#app').innerHTML=shell('<div class="empty"><h1>Клиент не найден</h1><a href="#clients">Вернуться к списку</a></div>');return}const tabs=[['overview','Информация',''],['applications','Заявки',c.apps.length],['documents','Документы',c.docs.length],['tasks','Задачи',c.tasks.filter(t=>!t.done).length],['mail','Почта',''],['reports','Отчёты',(c.reports||[]).length],['tests','Тесты',(c.tests||[]).length],['notes','Заметки','']];const tab=tabs.some(t=>t[0]===r.tab)?r.tab:'overview';let body='';
if(tab==='overview')body=clientOverview(c);
if(tab==='reports')body=renderReports(c);
if(tab==='applications')body=`<div class="section-top"><div><h2>Заявки в университеты</h2><p class="subtle">Отправлено ${completed(c)} из ${c.apps.length} · каждый статус можно изменить</p></div><button data-action="add-app" data-id="${c.id}">${icon('plus')} Заявка</button></div>${feeSummary(c)}${c.apps.map(a=>`<article class="app-card"><div class="section-top"><div class="person"><span class="uni-logo">${esc(a.university.split(' ').filter(w=>!['of','the'].includes(w)).slice(0,2).map(w=>w[0]).join(''))}</span><div><h3>${esc(a.university)}</h3><span class="subtle">${esc(a.program)}</span></div></div><button data-action="edit-app" data-id="${c.id}" data-app="${a.id}" aria-label="Изменить заявку ${esc(a.university)}" style="padding:6px 9px;font-size:12px">Изменить</button></div><div class="application-meta"><span>${esc(a.country)}</span><span>${icon('calendar')} До ${fmt(a.deadline)}</span><select aria-label="Статус заявки ${esc(a.university)}" data-status="${a.id}" data-client="${c.id}">${options(statuses,a.status)}</select></div><div class="application-fee"><span>Application fee</span><strong>${a.feeAmount===undefined||a.feeAmount===null?'Не указан':money(a.feeAmount,a.feeCurrency||'USD')}</strong><span class="badge ${a.feeStatus==='paid'?'green':''}">${feeLabels[a.feeStatus]||'Не указан'}</span>${a.feeStatus==='paid'&&a.feePaidDate?`<span class="subtle">${fullDate(a.feePaidDate)}</span>`:''}</div></article>`).join('')||'<div class="empty"><h3>Заявок пока нет</h3>Добавьте университет, программу и дедлайн.</div>'}`;
if(tab==='documents')body=`<div class="section-top"><h2>Документы клиента</h2><button data-action="add-doc" data-id="${c.id}">${icon('plus')} Ссылка</button></div><div class="notice">Файлы остаются в Google Drive. Здесь хранятся ссылки — CRM не меняет права доступа к документам.</div><div class="app-card"><div class="section-top" style="margin:0"><div><h3>Папка клиента</h3><span class="subtle">Фото, резюме, письма и другие документы</span></div>${googleLink(c.folder)?`<a href="${esc(googleLink(c.folder))}" target="_blank" rel="noopener noreferrer">Открыть папку</a>`:`<button data-action="edit-client" data-id="${c.id}">Привязать</button>`}</div></div>${c.docs.map(d=>`<div class="doc"><span class="file-icon">${icon('file')}</span><div><strong>${esc(d.name)}</strong><small>${esc(d.type)}</small></div><a href="${esc(googleLink(d.url))}" target="_blank" rel="noopener noreferrer">Открыть</a></div>`).join('')||'<div class="empty"><h3>Закрепите важные документы</h3>Добавьте ссылку на резюме, мотивационное письмо или фото.</div>'}`;
if(tab==='tasks')body=`<div class="section-top"><h2>Задачи клиента</h2><button data-action="add-task" data-id="${c.id}">${icon('plus')} Задача</button></div>${c.tasks.map(t=>taskRow(t,c,false)).join('')||'<div class="empty">Задач пока нет. Добавьте следующий шаг по поступлению.</div>'}`;
if(tab==='notes')body=`<div class="section-top"><h2>Внутренние заметки</h2><span class="subtle">Только для администратора</span></div><form id="notes-form" data-id="${c.id}"><label for="notes">Договорённости, предпочтения и следующий шаг</label><textarea id="notes" name="notes" class="textarea" maxlength="20000" placeholder="Что важно знать о клиенте…">${esc(c.notes)}</textarea><div class="form-footer"><button class="primary" type="submit">Сохранить заметку</button></div></form>`;
if(tab==='documents')body+=`<div class="btnrow"><button data-google="files" data-client="${c.id}">Загрузить файлы из папки Drive</button></div><div id="google-result"></div>`;
if(tab==='tests')body=renderClientTests(c);
if(tab==='mail')body=`<div class="section-top"><h2>Почта клиента</h2></div><p>Подключите Gmail с разрешения владельца. Здесь отображаются последние 20 писем подключённого ящика.</p><div class="btnrow"><button data-google="gmail" data-client="${c.id}">Подключить Gmail</button><button data-google="messages" data-client="${c.id}">Загрузить письма</button></div><div id="google-result"></div>`;
$('#app').innerHTML=shell(`<a class="back" href="#clients">${icon('arrow')} Все клиенты</a><div class="heading"><div class="profile-title">${avatar(c)}<div><h1>${esc(c.name)}</h1><p>${esc(c.level)} · поступление ${c.year}</p></div></div><div class="btnrow"><button data-action="whatsapp" data-id="${c.id}">${icon('mail')} WhatsApp</button><button data-action="edit-client" data-id="${c.id}">Редактировать</button></div></div><div class="detail-grid ${tab==='reports'?'report-layout':''}"><aside class="profile-panel"><h2 style="margin-bottom:24px">О клиенте</h2><dl>${[['Email',c.email||'Не указан'],['Телефон',c.phone||'Не указан'],['Страны',c.country||'Не указаны'],['Уровень',c.level],['Год поступления',c.year],['Университетов',new Set(c.apps.map(a=>a.university.trim().toLowerCase())).size]].map(([k,v])=>`<div class="field"><dt>${k}</dt><dd>${esc(v)}</dd></div>`).join('')}</dl><div class="summary-line">${badge(cstatus(c))}</div><p class="local-note">${c.demo?'Демонстрационный клиент. ':''}Данные сохраняются в базе.</p></aside><section><nav class="tabs" aria-label="Разделы карточки">${tabs.map(([id,label,count])=>`<a href="#client/${c.id}/${id}" class="${tab===id?'active':''}" ${tab===id?'aria-current="page"':''}>${label}${count!==''?` <span class="subtle">${count}</span>`:''}</a>`).join('')}</nav>${body}</section></div>`)}
function taskRow(t,c,showClient){return `<div class="task ${t.done?'done':''}"><input type="checkbox" id="task-${t.id}" data-task="${t.id}" data-client="${c.id}" ${t.done?'checked':''}><label for="task-${t.id}"><strong>${esc(t.title)}</strong><span>${showClient?esc(c.name)+' · ':''}${t.done?'Выполнено':days(t.date)<0?'Просрочено':days(t.date)===0?'Сегодня':'Срок'} · ${fmt(t.date)}</span></label>${showClient?`<a href="#client/${c.id}/tasks">Карточка</a>`:''}</div>`}
function renderTasks(){const pending=allTasks().filter(t=>!t.done).sort((a,b)=>a.date.localeCompare(b.date));const done=allTasks().filter(t=>t.done);$('#app').innerHTML=shell(`<div class="heading"><div><h1>Задачи</h1><p>${pending.length} открытых · ${pending.filter(t=>days(t.date)<0).length} просроченных</p></div><button class="primary" data-action="add-task">${icon('plus')} Добавить задачу</button></div><div class="full-tasks"><div class="section-top"><h2>Предстоящие</h2><span class="subtle">По сроку выполнения</span></div>${pending.map(t=>taskRow(t,t.client,true)).join('')||'<div class="empty">Все задачи выполнены.</div>'}${done.length?`<details style="margin-top:26px"><summary>Выполненные · ${done.length}</summary>${done.map(t=>taskRow(t,t.client,true)).join('')}</details>`:''}</div>`,'tasks')}
function renderIntegrations(){$('#app').innerHTML=shell(`<div class="heading"><div><h1>Интеграции</h1><p>Документы и переписка в карточках клиентов.</p></div></div><div class="integrations"><article class="integration"><h2>Google Drive и Docs</h2><p>Ссылки на папки и документы работают сразу. Для просмотра содержимого папок подключите ваш Google-аккаунт.</p><button data-google="drive">Подключить Google Drive</button></article><article class="integration"><h2>Gmail</h2><p>Подключение отдельно в карточке клиента. Чтение последних писем; отправка от имени клиента не включена.</p><a href="#clients">Выбрать клиента</a></article><article class="integration"><h2>WhatsApp</h2><p>Переход в чат по номеру клиента. Отчёт PDF можно прикрепить в WhatsApp вручную.</p><a href="#clients">Открыть клиентов</a></article></div><button data-google="status" style="margin-top:24px">Проверить подключения</button><div id="google-result"></div>`,'integrations')}
function appForm(c,a){showModal(a?'Редактировать заявку':'Добавить заявку',`<form id="application-form" data-client="${c.id}" data-app="${a?.id||''}"><label>Университет<input name="university" required maxlength="160" value="${esc(a?.university||'')}" placeholder="University of Toronto"></label><label>Программа<input name="program" required maxlength="160" value="${esc(a?.program||'')}" placeholder="Computer Science"></label><div class="row"><label>Страна<input name="country" required maxlength="80" value="${esc(a?.country||'')}"></label><label>Дедлайн<input name="deadline" type="date" required value="${a?.deadline||dateAt(30)}"></label></div><label>Статус<select name="status">${options(statuses,a?.status||statuses[0])}</select></label>${feeFields(a)}${footer(a?'Сохранить':'Добавить заявку')}</form>`)}
function taskForm(c){showModal('Новая задача',`<form id="task-form" data-client="${c?.id||''}">${c?'':`<label>Клиент<select name="client">${clients.map(c=>`<option value="${c.id}">${esc(c.name)}</option>`).join('')}</select></label>`}<label>Что нужно сделать<input name="title" required maxlength="250" placeholder="Проверить мотивационное письмо"></label><label>Срок<input name="date" type="date" required value="${dateAt(1)}"></label>${footer('Добавить задачу')}</form>`)}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;const c=clientById(b.dataset.id);switch(b.dataset.action){case'close':$('#modal').close();break;case'new-client':clientForm();break;case'edit-client':clientForm(c);break;case'add-app':appForm(c);break;case'edit-app':appForm(c,c.apps.find(a=>a.id===b.dataset.app));break;case'add-task':taskForm(c);break;case'add-doc':showModal('Добавить документ',`<form id="document-form" data-client="${c.id}"><label>Название<input name="name" required maxlength="160" placeholder="Резюме · английская версия"></label><label>Тип документа<select name="type">${options(['Резюме','Мотивационное письмо','Рекомендация','Фото','Диплом / транскрипт','Другой документ'])}</select></label><label>Ссылка Google Drive или Docs<input name="url" type="url" required placeholder="https://docs.google.com/document/d/…"></label>${footer('Добавить ссылку')}</form>`);break;case'gmail-info':showModal('Подключение Gmail',`<p>В рабочей системе клиент получит ссылку и разрешит доступ к почте на странице Google. Передавать пароль не нужно.</p><p>Для запуска нужно настроить приложение Google, безопасное хранение разрешений и пройти необходимые проверки Google. В этом прототипе доступа к почте нет.</p><div class="notice">Первый этап — только чтение писем. Отправка ответов от имени клиента не включена.</div><div class="form-footer"><button class="primary" data-action="close">Понятно</button></div>`);break;case'whatsapp':if(!c.phone){showModal('Добавьте номер телефона',`<p>Чтобы открыть WhatsApp клиента, укажите его телефон в международном формате.</p><div class="form-footer"><button class="primary" data-action="edit-client" data-id="${c.id}">Добавить телефон</button></div>`)}else{window.open('https://wa.me/'+c.phone.replace(/\D/g,''),'_blank','noopener,noreferrer')}break}});
document.addEventListener('change',async e=>{const el=e.target;if(el.dataset.status){const c=clientById(el.dataset.client);c.apps.find(a=>a.id===el.dataset.status).status=el.value;if(await save())toast('Статус заявки сохранён');render()}if(el.dataset.task){const c=clientById(el.dataset.client);c.tasks.find(t=>t.id===el.dataset.task).done=el.checked;await save();render()}});
document.addEventListener('submit',async e=>{const f=e.target;if(!['client-form','application-form','task-form','document-form','notes-form'].includes(f.id))return;e.preventDefault();const data=Object.fromEntries([...new FormData(f)].map(([k,v])=>[k,String(v).trim()]));const error=text=>{if($('#form-error'))$('#form-error').textContent=text;else toast(text)};let target;
if(f.id==='client-form'){if(!data.name)return error('Укажите имя клиента.');if(data.folder&&!googleLink(data.folder))return error('Укажите HTTPS-ссылку на drive.google.com или docs.google.com.');if(data.phone&&!/^\+?[\d\s()\-]+$/.test(data.phone))return error('Используйте номер в международном формате, например +7 700 000 00 00.');if(data.phone&&(data.phone.replace(/\D/g,'').length<10||data.phone.replace(/\D/g,'').length>15))return error('В номере должно быть от 10 до 15 цифр, включая код страны.');const values={...data,year:Number(data.year)};target=clientById(f.dataset.id);if(target)Object.assign(target,values);else{target={id:crypto.randomUUID(),...values,apps:[],docs:[],tasks:[],notes:'',demo:false};clients.unshift(target)} }
if(f.id==='application-form'){if(!data.university||!data.program||!data.country)return error('Заполните университет, программу и страну.');try{Object.assign(data,validateFee(data))}catch(err){return error(err.message)}target=clientById(f.dataset.client);const existing=target.apps.find(a=>a.id===f.dataset.app);if(existing)Object.assign(existing,data);else target.apps.push({id:crypto.randomUUID(),...data})}
if(f.id==='document-form'){if(!data.name)return error('Введите название документа.');if(!googleLink(data.url))return error('Поддерживаются HTTPS-ссылки на drive.google.com и docs.google.com.');target=clientById(f.dataset.client);target.docs.push({id:crypto.randomUUID(),...data,url:googleLink(data.url)})}
if(f.id==='task-form'){if(!data.title)return error('Опишите задачу.');target=clientById(f.dataset.client||data.client);target.tasks.push({id:crypto.randomUUID(),title:data.title,date:data.date,done:false})}
if(f.id==='notes-form'){target=clientById(f.dataset.id);target.notes=data.notes;if(await save())toast('Заметка сохранена');return}
const ok=await save();if(!ok)return;$('#modal').close();if(f.id==='client-form')location.hash=`client/${target.id}`;else if(f.id==='application-form')location.hash=`client/${target.id}/applications`;else if(f.id==='document-form')location.hash=`client/${target.id}/documents`;render();if(ok)toast('Сохранено в базе');
});
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'search_applicants',title:'Поиск клиентов CRM',description:'Найти клиентов по имени или email в демонстрационной CRM. Только чтение.',inputSchema:{type:'object',properties:{query:{type:'string'}},required:['query'],additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute(input){if(!input||typeof input.query!=='string')throw new Error('query must be a string');return clients.filter(c=>`${c.name} ${c.email}`.toLowerCase().includes(input.query.toLowerCase())).slice(0,20).map(c=>({id:c.id,name:c.name,level:c.level,applications:c.apps.length}))}})).catch(()=>{})}catch{}}
function shell(body,active='clients'){
 const user=crmUser||crmSettings.currentUser||{name:'Пользователь',role:'staff'},owner=user.role==='owner',initials=(user.name||user.email||'U').split(/\s+/).map(value=>value[0]).slice(0,2).join('').toUpperCase();
 const navigation=[['clients','people','Клиенты',clients.length],['tasks','calendar','Задачи',allTasks().filter(task=>!task.done&&days(task.date)<=7).length],['integrations','link','Интеграции',''],['settings','grid','Настройки','']];
 const pageName=active==='clients'?'Клиенты':active==='tasks'?'Задачи':active==='settings'?'Настройки':'Интеграции';
 return `<div class="shell"><aside class="sidebar"><a href="#clients" class="brand" aria-label="${esc(crmSettings.organization||'GrantEd')} — главная">${brandLogo()}</a><p class="eyebrow">Рабочее пространство</p><nav class="nav" aria-label="Основное меню">${navigation.map(([id,ic,label,count])=>`<a href="#${id}" class="${active===id?'active':''}" ${active===id?'aria-current="page"':''}>${icon(ic)}${label}<span class="count">${count}</span></a>`).join('')}</nav><div class="sidebar-bottom"><button data-session="logout">Выйти</button>${owner?'<a href="/api/export" class="quiet-link">Скачать резервную копию JSON</a>':''}${owner&&clients.length===0?'<button data-session="import">Импорт из прототипа</button>':''}<div class="season"><small>Цикл поступления</small><br><strong>Набор ${esc(crmSettings.year)}</strong></div><div class="account"><span class="avatar">${esc(initials)}</span><div>${esc(user.name||user.email)}<small>${owner?'Владелец':'Сотрудник'}</small></div></div></div></aside><main class="main"><header class="topbar"><span>Рабочее пространство <span style="margin:0 10px;color:#b0b7c1">/</span> <strong>${pageName}</strong></span><span class="demo">Команда · ${crmSettings.teamCount||0}/10</span><span class="today">${today.toLocaleDateString('ru-RU',{day:'numeric',month:'long',year:'numeric'})}</span></header><div class="content">${body}</div></main></div>`;
}
initReports();
startCRM();
